(function () {
  var session, refreshed = false, finished = false;
  function finish(message) {
    if (finished) return;
    finished = true;
    console.log("[XC签到 v3.0.0] " + message);
    try { $persistentStore.write(new Date().toISOString() + " | " + message, "xc_checkin_result"); } catch (_) {}
    XC.notify("星驰API签到", message);
    $done();
  }
  function guarded(fn) {
    return function () {
      if (finished) return;
      try { fn.apply(null, arguments); }
      catch (_) { finish("执行异常，未继续签到；请检查凭证存储或更新插件。"); }
    };
  }
  function stable() {
    if (XC.same(session)) return true;
    finish("登录会话已变化，本次停止，避免签错账号；请重新运行。");
    return false;
  }
  function params(path, body, authorize) {
    var headers = {"Content-Type": "application/json"};
    if (authorize) headers.Authorization = "Bearer " + session.access;
    if (session.cookie) headers.Cookie = session.cookie;
    var p = {url: session.host + path, headers: headers, timeout: 15000};
    if (body !== null) p.body = JSON.stringify(body);
    return p;
  }
  function failure(stage, resp, data) {
    var code = XC.object(data) && String(data.code);
    if (!code || !/^[A-Za-z0-9_ -]{1,48}$/.test(code)) code = "UNKNOWN";
    finish(stage + "失败（HTTP " + XC.status(resp) + "，业务码 " + code + "）；未确认签到成功。");
  }
  function renew() {
    if (refreshed) { finish("续期后仍未通过鉴权，请重新登录捕获配套凭证。"); return; }
    refreshed = true;
    if (!session.refresh) {
      finish("访问凭证已失效，尚无配套续期凭证；请更新插件后登录一次。");
      return;
    }
    if (!stable()) return;
    var before = session;
    $httpClient.post(params("/api/v1/auth/refresh", {refresh_token: before.refresh}, false), guarded(function (err, resp, body) {
      if (err) { finish("续期网络错误，本次停止；凭证未清空，请稍后重试。"); return; }
      var j = XC.json(body);
      if (!XC.success(resp) || !XC.object(j) || j.code !== 0) {
        failure("续期", resp, j); return;
      }
      var pair = XC.pair(j.data, before.host, before.cookie, before);
      if (!pair) { finish("续期响应缺少完整凭证，本次停止，请重新登录。"); return; }
      var now = XC.read();
      // The response hook may have committed this exact pair before this callback.
      if (now && now.host === pair.host && now.access === pair.access && now.refresh === pair.refresh) {
        session = now;
      } else {
        if (!XC.same(before)) {
          finish("续期期间账号或凭证已变化，已忽略旧响应，未继续签到。"); return;
        }
        session = XC.write(pair);
      }
      query(); // Recheck status before retrying a POST; the first attempt may have raced.
    }));
  }
  function call(method, callback) {
    if (!stable()) return;
    $httpClient[method.toLowerCase()](params("/api/v1/user/checkin", method === "POST" ? {} : null, true), guarded(function (err, resp, body) {
      if (!stable()) return;
      if (err) {
        finish(method === "POST" ? "签到网络异常，结果未知；请先查询状态，未自动重发。" : "状态查询网络错误，本次未签到。");
        return;
      }
      if (XC.status(resp) === 401) { renew(); return; }
      callback(resp, XC.json(body));
    }));
  }
  function reward(value) {
    if (typeof value !== "number" && !(typeof value === "string" && /^\d+(?:\.\d+)?$/.test(value))) return null;
    return isFinite(Number(value)) && Number(value) >= 0 ? String(value) : null;
  }
  function sign() {
    call("POST", function (resp, j) {
      var status = XC.status(resp);
      if (status >= 200 && status < 500 && XC.object(j) &&
          (j.reason === "CHECKIN_ALREADY_CLAIMED" || j.code === "CHECKIN_ALREADY_CLAIMED")) {
        finish("今日已签到（重复请求），跳过。"); return;
      }
      if (!XC.success(resp) || !XC.object(j) || j.code !== 0) { failure("签到", resp, j); return; }
      var amount = XC.object(j.data) ? reward(j.data.amount) : null;
      if (amount === null) {
        finish("签到接口返回成功但缺少有效到账额度，结果需核对；未自动重发。"); return;
      }
      finish("签到成功 +" + amount + " 额度 🎉");
    });
  }
  function query() {
    call("GET", function (resp, j) {
      if (!XC.success(resp) || !XC.object(j) || j.code !== 0 || !XC.object(j.data)) {
        failure("状态查询", resp, j); return;
      }
      var d = j.data;
      if (d.enabled === false) { finish("本站未开启签到功能。"); return; }
      if (d.enabled !== true || typeof d.claimed_today !== "boolean") {
        finish("状态响应缺少有效的签到状态，本次未发起签到。"); return;
      }
      if (d.claimed_today) { finish("今日已签到，跳过。"); return; }
      sign();
    });
  }
  try {
    session = XC.read();
    if (!session) { finish("未找到访问凭证，请登录网站捕获，或运行手动设置脚本。"); return; }
    query();
  } catch (_) {
    finish("凭证读取或存储失败，本次未继续签到；请检查存储或重新手动设置。");
  }
})();
